head.script:
scwin.screenId = "jldfil16650";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil16650.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.rd_division_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.rd_division_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin rd_division_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.search(01)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil16650.rd_division_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param num
 * @returns
 * @hidden N
*/
scwin.search = function (num) {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (num === '01') {
        ($c.util.getComponent("listing01") && $c.util.getComponent("listing01").show ? $c.util.getComponent("listing01").show() : console.warn('[sdd] show 대상 미해결: ' + "listing01"));
        ($c.util.getComponent("listing02") && $c.util.getComponent("listing02").hide ? $c.util.getComponent("listing02").hide() : console.warn('[sdd] hide 대상 미해결: ' + "listing02"));
    } else {
        ($c.util.getComponent("listing01") && $c.util.getComponent("listing01").hide ? $c.util.getComponent("listing01").hide() : console.warn('[sdd] hide 대상 미해결: ' + "listing01"));
        ($c.util.getComponent("listing02") && $c.util.getComponent("listing02").show ? $c.util.getComponent("listing02").show() : console.warn('[sdd] show 대상 미해결: ' + "listing02"));
    }
    /* sdd-asis-lifecycle:end */
};
